contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Single test function driving the minimal calls and ending with one assert.
    // Params:
    // - whale: address to pass to C's constructor is irrelevant here because C is already deployed.
    // - openAmount: amount of wei to wager/donate; must equal the bet limit we set.
    // - newBetLimit: desired bet limit to set via AdjustBetAmounts.
    // We do not read msg.value; the caller must fund this contract so it can forward value.
    function runTest(address player, uint256 newBetLimit, uint256 openAmount) public {
        // Preconditions for the test to be meaningful and to avoid reverts in original contract:
        // newBetLimit must be > 0 and equal to openAmount so wager() requires pass.
        require(newBetLimit > 0, "newBetLimit must be > 0");
        require(openAmount == newBetLimit, "openAmount must equal newBetLimit");

        // 1) Owner-only calls require msg.sender == owner. The deployed C's owner is unknown.
        // To make this test meaningful we assume the invoker of this test contract is the owner of C.
        // So the caller of runTest must also be C.owner. No programmatic check here.

        // Open contract to public so wagers are allowed.
        c.OpenToThePublic();

        // Set the bet limit to newBetLimit. In P this sets betLimit = newBetLimit; in M it sets 0.
        c.AdjustBetAmounts(newBetLimit);

        // Ensure this contract has enough ETH to forward the wager. Caller must have funded this contract.
        require(address(this).balance >= openAmount, "Insufficient balance in test contract");

        // Place the wager for 'player'. The contract C.wager() uses msg.sender, so we must have player call
        // through this contract. We achieve that by requiring the test caller to be the player and have them
        // call c.wager{value: openAmount} directly — but rules require interacting only through c from this contract.
        // Alternative: we simulate player as this contract by calling c.wager with value; then the recorded player is address(this).
        // So we treat the player parameter as unused for the actual wager check and instead verify for address(this).

        // Make the wager from this contract (this contract becomes the player in C).
        c.wager{value: openAmount}();

        // Check that C records this contract as having wagered. In P this is true; in M, because betLimit was set to 0,
        // wager() would revert when require(msg.value == betLimit) since openAmount>0 != 0, so the previous call would have reverted.
        // Therefore reaching here already distinguishes P vs M. To make a single final assert, we assert that hasPlayerWagered(this contract) == true.

        // Final single assertion required by the harness.
        assert(c.hasPlayerWagered(address(this)) == true);
    }

    // allow this test contract to receive ETH so it can forward wagers
    receive() external payable {}
}

